#!/bin/bash
# A committed project whose CLAUDE.md scopes reviews (skip generated files,
# leave formatting to black), plus an uncommitted change that is correct.
set -euo pipefail
git init -q
git config user.name "Eval Fixture"
git config user.email "fixture@example.com"
mkdir -p app gen tests
cat > CLAUDE.md <<'MD'
# Text tools

- Run the tests with `python -m unittest`.
- Reviewers: skip the files under `gen/`; `make gen` writes them from
  `schema.json`. Formatting is enforced by black, so don't comment on it.
MD
cat > gen/models.py <<'PY'
# Generated by `make gen` from schema.json. Do not edit.
FIELDS = ("title", "body")
PY
cat > app/text.py <<'PY'
"""Small helpers for plain text."""
PY
touch tests/__init__.py
git add -A
git commit -qm "Add text helpers"
cat >> app/text.py <<'PY'


def word_count(text: str) -> int:
    """The number of words in text, where words are separated by whitespace."""
    return len(text.split())
PY
cat > tests/test_text.py <<'PY'
import unittest

from app.text import word_count


class WordCount(unittest.TestCase):
    def test_counts_words(self):
        self.assertEqual(word_count("one two  three"), 3)

    def test_empty_and_blank_text_have_no_words(self):
        self.assertEqual(word_count(""), 0)
        self.assertEqual(word_count(" \t\n"), 0)


if __name__ == "__main__":
    unittest.main()
PY
